<script setup lang="ts">import {computed} from 'vue';const props=defineProps<{points:{x:number;y:number}[];title:string}>();const path=computed(()=>props.points.map((p,i)=>(i?'L':'M')+(45+p.x*505)+','+(260-p.y*215)).join(' '));</script><template><figure class="plot"><figcaption>{{title}} <span>独立留出集</span></figcaption><svg viewBox="0 0 580 300" role="img" :aria-label="title"><g class="grid-lines"><path v-for="i in 5" :key="i" :d="`M45 ${260-i*43} H550 M${45+i*101} 45 V260`"/></g><path d="M45 45 V260 H550" class="axis"/><path :d="path" class="curve"/><text x="35" y="280">0</text><text x="540" y="280">1</text><text x="25" y="50">1</text></svg></figure></template>
